@startuml
class Center {
  +name : string
  +address : string
}

class Room {
  +number : int
  +maxCapacity : int
}

class Person {
  +firstName : string
  +familyName : string
  +birthDate : date
}

class Trainer {
  +diploma : string
}

class Session {
  +date : date
  +startingHour : time
}

class GroupSession {
  +type : string
}

class IndividualSession {
}

Center "1" *-- "1..*" Room
Person <|-- Trainer
Person <|-- Member
Session <|-- GroupSession
Session <|-- IndividualSession

Center "1" -- "*" Session
Room "1" -- "*" Session
Trainer "0..1" -- "*" GroupSession : supervises
Member "*" -- "*" Session : participates
@enduml

